"use strict";
/* ---------- Computing 101 : 27 leçons pour 13 modules (132 challenges sur le site, 130 lus) ----------
   Contenu récupéré le 18 novembre 2026 sur https://pwn.college/computing-101/ (lecture connectée) :
   130 défis sur 132 lus ; les 2 défis verrouillés du module Debugging Refresher (« Modifying
   Execution » et « Broken Functions ») n’ont pas pu être lus et sont signalés comme non
   disponibles dans la leçon C101-25, sans contenu inventé. Les cours du site sont des vidéos,
   non transcrites : ces leçons travaillent à partir des sujets des défis.
   Leçons ORIGINALES écrites en français pour Nexus Guardian, adaptées des sujets des modules —
   aucun texte du site n’est copié, aucun mot de passe ni flag de challenge n’est reproduit.
   Les gros modules sont découpés : Software Introspection en 3 leçons, Control Flow en 3,
   Numbers as Strings en 4. */
var DOJO_C101_LESSONS = [
  { id:"C101-01", mod:"Your First Program", t:"Ton premier programme : les registres, mémoire courte du processeur", sub:"Un programme est une suite d’instructions ; rax et eax sont ses cases de travail immédiates.",
    read:["Changement d’échelle : après avoir lancé des programmes, tu vas en écrire un, au plus près du processeur. Un programme, à ce niveau, est une suite d’instructions que le processeur exécute une à une, dans l’ordre. Pour travailler, il dispose de cases ultra-rapides intégrées : les registres.",
      "Le registre vedette de ce dojo s’appelle rax : 64 bits de mémoire de travail immédiate. Sa moitié basse, les 32 bits du bas, porte un autre nom : eax. Écrire dans eax, c’est donc écrire dans le bas de rax — les deux noms désignent des morceaux du même registre, pas deux registres séparés.",
      "L’instruction de base est mov : elle copie une valeur dans un registre. « mov rax, 42 » place le nombre 42 dans rax. La source garde sa valeur : mov copie, il ne déplace pas — malgré son nom. Tout le dojo se construit sur ce geste minuscule."],
    term:"mov rax, 42\n<span class=\"tdim\">Copier 42 dans rax · eax = les 32 bits bas de rax.</span>",
    ex:{ type:"qcm", q:"Que se passe-t-il quand le processeur exécute « mov rax, 42 » ?",
      opts:["Le nombre 42 est copié dans le registre rax", "Le programme se termine avec le code 42", "Le nombre 42 est affiché à l’écran"], ok:0 },
    why:"mov est une copie vers un registre, rien de plus — mais c’est le geste fondateur : charger une valeur, c’est préparer tout ce qui suit (un calcul, un appel système, un code de sortie). L’affichage et la fin du programme demandent d’autres instructions, qui arrivent dès la leçon suivante." },
  { id:"C101-02", mod:"Your First Program", t:"Parler au système : syscall, exit et code de sortie", sub:"Le système d’exploitation travaille sur demande ; le numéro de la demande va dans rax.",
    read:["Un programme seul ne peut presque rien faire : afficher, lire un fichier, terminer proprement — tout passe par le système d’exploitation. Pour lui demander un service, on utilise un appel système, un syscall : on place le numéro du service demandé dans rax, ses paramètres dans des registres prévus (le premier dans rdi), puis on exécute l’instruction syscall. Linux en compte environ 330.",
      "Le premier à connaître est exit, le numéro 60 : il termine le programme en rendant un code de sortie, placé dans rdi. Ce code, le shell le récupère dans la variable « $? » : « echo $? » affiche le code du dernier programme lancé. Zéro signifie en général « tout s’est bien passé », le reste signale une fin particulière ou une erreur.",
      "Pour fabriquer un vrai programme : on écrit le code assembleur dans un fichier source (qui commence par déclarer la syntaxe utilisée et un point d’entrée nommé _start), on l’assemble avec l’outil as, on le lie avec ld, et on lance l’exécutable obtenu. Et mov sait aussi copier d’un registre à l’autre : « mov rdi, rsi » recopie la valeur de rsi dans rdi — la source la conserve."],
    term:"$ as -o prog.o prog.s\n$ ld -o prog prog.o\n$ ./prog ; echo $?\n<span class=\"tdim\">Assembler, lier, lancer · « $? » : le code de sortie du dernier programme.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la fabrication et la vérification d’un premier programme :",
      items:["Écrire le code assembleur dans un fichier source, avec son point d’entrée _start", "Assembler le source avec as pour obtenir un fichier objet", "Lier le fichier objet avec ld pour obtenir l’exécutable", "Lancer l’exécutable, puis lire son code de sortie avec echo $?"],
      disp:[2,0,3,1] },
    why:"Écrire, assembler, lier, lancer, vérifier : la chaîne complète tient en quatre gestes que tu répéteras dans tout le dojo. Et le code de sortie est ton premier outil de dialogue avec un programme : avant même de savoir afficher du texte, un programme peut déjà te répondre par un nombre." },
  { id:"C101-03", mod:"Computer Memory", t:"La mémoire : des adresses et des crochets", sub:"La mémoire est immense et lente ; les crochets [ ] vont y chercher une valeur.",
    read:["Les registres sont rapides mais minuscules. La mémoire vive, elle, est immense — des milliards d’octets — mais plus lente d’accès. Un programme vit entre les deux : il range ses données en mémoire et les ramène dans les registres pour travailler dessus. Comprendre ce va-et-vient, c’est comprendre la moitié de l’informatique bas niveau.",
      "Chaque octet de mémoire porte un numéro : son adresse. Les adresses se suivent comme les numéros d’une très longue rue. Pour lire ce qui se trouve à une adresse, l’assembleur utilise des crochets : écrire une adresse entre [ ] signifie « la valeur rangée à cette adresse », et non l’adresse elle-même. C’est le déréférencement.",
      "La taille lue dépend du registre de destination : charger dans un registre 64 bits lit 8 octets d’un coup, à partir de l’adresse indiquée. Retiens la distinction fondamentale du module : une adresse est un numéro de casier ; la valeur entre crochets est ce qu’il y a DANS le casier."],
    term:"mov rdi, [4096]\n<span class=\"tdim\">Lire les 8 octets rangés à l’adresse 4096 et les placer dans rdi · Sans crochets, on copierait le nombre 4096 lui-même.</span>",
    ex:{ type:"qcm", q:"Quelle est la différence entre « mov rdi, 4096 » et « mov rdi, [4096] » ?",
      opts:["Aucune, les crochets sont décoratifs", "Sans crochets, rdi reçoit le nombre 4096 ; avec crochets, rdi reçoit la valeur rangée à l’adresse 4096", "Avec crochets, le programme écrit en mémoire au lieu de lire"], ok:1 },
    why:"Les crochets changent tout : ils transforment un numéro en contenu. C’est le mécanisme central de ce module — et plus tard, de presque toutes les failles mémoire : confondre une adresse et la valeur qu’elle désigne est l’erreur que tout ce dojo t’apprend à ne plus faire." },
  { id:"C101-04", mod:"Computer Memory", t:"Pointeurs, décalages et double détour", sub:"Une adresse dans un registre s’appelle un pointeur — et les pointeurs se chaînent.",
    read:["Quand une adresse vit dans un registre, ce registre joue le rôle de pointeur : il « pointe » vers une valeur rangée en mémoire. Déréférencer le pointeur, c’est suivre la flèche : écrire le registre entre crochets lit la valeur à l’adresse qu’il contient. Un même registre peut même recevoir le résultat : le pointeur est alors remplacé par la valeur pointée.",
      "Les données rangées en mémoire se suivent souvent en rangée : après une première valeur viennent ses voisines, à des adresses légèrement plus grandes. On atteint une voisine en ajoutant un décalage au pointeur, compté en octets : [registre+8] désigne la valeur 8 octets plus loin — la suivante, quand les valeurs font 8 octets.",
      "Dernier niveau : une adresse peut elle-même être rangée en mémoire. Le casier contient alors le numéro d’un autre casier. Pour atteindre la valeur finale, on déréférence deux fois de suite : le premier chargement donne la seconde adresse, le second donne la valeur. C’est le double déréférencement — des chaînes de pointeurs comme celle-là structurent toutes les données complexes."],
    term:"mov rax, [rdi]\nmov rax, [rax]\n<span class=\"tdim\">Premier chargement : une adresse · Second chargement : la valeur rangée à cette adresse.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre un double déréférencement :",
      items:["Partir d’une première adresse connue", "Lire à cette adresse : on y trouve une seconde adresse", "Lire à la seconde adresse : on y trouve la valeur cherchée", "Utiliser la valeur (par exemple comme code de sortie)"],
      disp:[1,3,0,2] },
    why:"Chaque déréférencement franchit un niveau d’indirection : adresse, adresse, valeur. Visualiser cette chaîne évite l’erreur classique — utiliser la seconde adresse comme si c’était déjà la valeur. En sécurité, suivre ces chaînes est le quotidien de l’analyse mémoire." },
  { id:"C101-05", mod:"The Stack", t:"La pile au lancement : rsp, argc et pop", sub:"Au démarrage, le noyau dépose les arguments du programme sur la pile, sous rsp.",
    read:["Il existe une zone de mémoire spéciale que tu as déjà croisée sans la voir : la pile. C’est une structure « dernier entré, premier sorti » — comme une pile d’assiettes — dont le sommet est désigné par un registre dédié : rsp, le pointeur de pile. Au lancement d’un programme, le noyau y dépose les informations de départ.",
      "La toute première valeur, à l’adresse même de rsp, est argc : le nombre d’arguments du programme, son propre nom compris. Juste après viennent, de 8 octets en 8 octets, des pointeurs vers chaque argument écrit en texte : [rsp+8] mène au nom du programme, [rsp+16] à son premier vrai argument, et ainsi de suite. Atteindre le texte d’un argument demande donc deux lectures : le pointeur sur la pile, puis la chaîne à l’adresse pointée.",
      "Pour prendre la valeur du sommet, l’instruction pop la copie dans un registre ET avance rsp de 8 : la valeur est « dépilée ». C’est le geste miroir de push, qui recule rsp et range une valeur. Toute la vie d’un programme — appels de fonctions, variables locales — se joue sur ces deux gestes."],
    term:"$ ./prog alpha beta\n<span class=\"tdim\">Sur la pile au départ : argc = 3, puis les pointeurs vers « prog », « alpha », « beta ».</span>",
    ex:{ type:"qcm", q:"Au tout début d’un programme, que contient la valeur située à [rsp] ?",
      opts:["Le premier argument écrit en texte", "argc : le nombre d’arguments du programme, nom du programme compris", "Le code de sortie du programme précédent"], ok:1 },
    why:"La pile de départ est un contrat du noyau : argc d’abord, puis les pointeurs d’arguments, chacun occupant 8 octets. Savoir lire ce contrat, c’est pouvoir récupérer ce que l’utilisateur a vraiment tapé — la base des modules sur les chaînes et la calculatrice, plus loin dans ce dojo." },
  { id:"C101-06", mod:"Nibbling on Numbers", t:"Bits, nibbles et hexadécimal", sub:"Un octet vaut 8 bits, un nibble en vaut 4 — et un chiffre hex couvre exactement un nibble.",
    read:["Tout ce que manipule un processeur est fait de bits : des chiffres qui valent 0 ou 1. Huit bits forment un octet, l’unité de base de la mémoire. La moitié d’un octet — 4 bits — a son propre nom : un nibble. Ce découpage n’est pas un caprice : il épouse parfaitement l’hexadécimal.",
      "Un chiffre hexadécimal vaut de 0 à 15 : il décrit donc exactement 4 bits, un nibble. Deux chiffres hex décrivent un octet complet, de 0x00 à 0xff. Les préfixes évitent les confusions : « 0b » annonce du binaire, « 0x » de l’hexadécimal, et un nombre sans préfixe se lit en décimal.",
      "Convertir devient mécanique : coupe l’octet binaire en deux groupes de 4 bits, traduis chaque groupe en un chiffre hex. Par exemple, 1010 0101 devient a5, écrit 0xa5. Dans l’autre sens, chaque chiffre hex se réécrit en 4 bits, zéros initiaux compris : 0x0a donne 0000 1010."],
    term:"10100101 → 1010 0101 → a 5 → 0xa5\n<span class=\"tdim\">Deux groupes de 4 bits, deux chiffres hex : un octet entier, sans reste.</span>",
    ex:{ type:"qcm", q:"Combien de chiffres hexadécimaux faut-il pour écrire un bloc de trois octets ?",
      opts:["Trois, un par octet", "Six : chaque octet demande deux chiffres hex", "Douze, un par bit"], ok:1 },
    why:"Le mariage bit-nibble-hex est parfait : 1 chiffre hex = 4 bits, donc 2 chiffres = 1 octet, et 6 chiffres = 3 octets. C’est pour cette régularité que les adresses, les dumps mémoire et les empreintes s’écrivent en hexadécimal plutôt qu’en binaire interminable." },
  { id:"C101-07", mod:"Nibbling on Numbers", t:"Les négatifs sans magie : le complément à deux", sub:"Le bit du haut devient le signe, et l’arithmétique ordinaire continue de marcher.",
    read:["Comment ranger un nombre négatif dans des bits ? Une première idée — réserver le bit du haut comme signe — produit deux zéros (+0 et −0) et une arithmétique bancale. L’informatique a choisi mieux : le complément à deux, où le bit du haut pèse négativement. Résultat : un seul zéro, et les additions fonctionnent sans traitement spécial.",
      "En 8 bits, la valeur dont tous les bits sont à 1 vaut −1 en lecture signée (et 255 en lecture non signée : c’est le contexte qui décide). Les bornes suivent la taille : en 16 bits signé, de −32768 à 32767 ; en 32 bits, le maximum signé vaut 2147483647. Règle de lecture : si le bit du haut est à 1, la valeur signée est la valeur non signée moins 2 puissance n (256 en 8 bits, 65536 en 16 bits…).",
      "Encoder fait le trajet inverse : une valeur négative s’écrit comme elle-même plus 2 puissance n — −5 en 8 bits devient 251. Autre recette équivalente : inverser tous les bits de la valeur positive, puis ajouter 1. Les deux donnent le même motif de bits : c’est lui qui voyage en mémoire, pas le signe."],
    term:"−5 en 8 bits : −5 + 256 = 251 = 11111011\n<span class=\"tdim\">Le bit du haut à 1 annonce le négatif · Lu en non signé, le même motif vaut 251.</span>",
    ex:{ type:"qcm", q:"En 8 bits signés (complément à deux), que vaut le motif 11111111 ?",
      opts:["255", "−1", "−255"], ok:1 },
    why:"Tous les bits à 1, c’est −1 : la valeur non signée 255, moins 256, donne −1. Retiens ce motif — il réapparaîtra partout, des extensions de signe aux dumps mémoire. Et note la leçon générale : les bits ne portent pas leur interprétation ; signé ou non signé, c’est le programme qui choisit." },
  { id:"C101-08", mod:"Software Introspection", t:"Voir sans lancer : objdump et strace", sub:"Deux loupes complémentaires : le code figé d’un côté, les appels système de l’autre.",
    read:["Les programmes réels buggent, et souvent, on doit comprendre un code qu’on n’a pas écrit. Ce module construit la boîte à outils d’introspection — les mêmes gestes servent à corriger, à auditer et, plus tard dans le parcours, à exploiter. Premier outil : objdump, qui désassemble un exécutable — il retraduit le code machine brut, suite d’octets illisibles, en instructions assembleur lisibles.",
      "Deuxième outil : strace, qui trace les appels système d’un programme en cours d’exécution. Chaque ligne montre un service demandé au système et ses paramètres, tels quels : on y voit par exemple une demande de terminaison avec son code, ou un minuteur armé avec sa durée. Là où objdump montre ce que le programme PEUT faire, strace montre ce qu’il FAIT, cette fois-ci.",
      "Le réflexe d’analyste se résume ainsi : statique d’abord (objdump, pour la carte du code), dynamique ensuite (strace, pour le trajet réel). Et souviens-toi de Linux Luminarium : l’outil strings complète le tableau en extrayant les textes lisibles d’un binaire."],
    term:"$ objdump -d -M intel ./prog\n$ strace ./prog\n<span class=\"tdim\">objdump : le code, figé et désassemblé · strace : les appels système, en direct.</span>",
    ex:{ type:"qcm", q:"Tu veux connaître la valeur exacte passée à un appel système pendant une exécution précise. Quel outil répond ?",
      opts:["objdump, qui montre le code désassemblé", "strace, qui trace les appels système avec leurs paramètres, en direct", "ls, qui liste le dossier du programme"], ok:1 },
    why:"objdump est statique : il montre le code, pas son exécution. strace est dynamique : il intercepte chaque appel système au moment où il passe, paramètres compris. Les deux regards se complètent — la carte, puis le trajet." },
  { id:"C101-09", mod:"Software Introspection", t:"GDB pas à pas : starti, stepi, print, set", sub:"Le débogueur exécute ton programme au ralenti, une instruction à la fois.",
    read:["Troisième outil, le plus puissant : GDB, le débogueur. On le lance sur un binaire, et il attend tes ordres avant même la première instruction. La commande starti démarre le programme en s’arrêtant dès le début ; disassemble affiche alors les instructions autour du point d’exécution.",
      "L’avancement se fait au pas : stepi (raccourci si) exécute exactement une instruction, puis s’arrête à nouveau. Entre deux pas, print lit l’état : « print $rdi » affiche la valeur courante du registre rdi — le préfixe « $ » désigne les registres et variables du débogueur. On observe ainsi un secret se charger dans un registre, instruction après instruction.",
      "Et GDB ne fait pas que regarder : set modifie l’état, par exemple « set $rax = 42 » réécrit un registre avant de continuer. Observer, avancer, corriger, reprendre : c’est la boucle du débogage. Pour sortir, quit — ou simplement q."],
    term:"(gdb) starti\n(gdb) stepi\n(gdb) print $rdi\n<span class=\"tdim\">Démarrer au tout début · Avancer d’une instruction · Lire un registre.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre une première session de débogage :",
      items:["Charger le programme dans GDB", "Démarrer avec starti et s’arrêter à la première instruction", "Avancer instruction par instruction avec stepi", "Lire la valeur d’un registre avec print"],
      disp:[2,0,3,1] },
    why:"Charger, démarrer au début, avancer au pas, observer : cette discipline transforme un programme opaque en film image par image. La plupart des blocages en analyse viennent d’un pas sauté — GDB sert précisément à n’en sauter aucun." },
  { id:"C101-10", mod:"Software Introspection", t:"GDB : mémoire, arrêts coopératifs et entrées préparées", sub:"Examiner la pile, laisser le programme s’arrêter lui-même, et contrôler ce qu’il reçoit.",
    read:["La commande x de GDB examine la mémoire : « x $rsp » montre ce qui se trouve au sommet de la pile, et des variantes précisent le format — par exemple en décimal plutôt qu’en hexadécimal, format par défaut. En visant une adresse obtenue depuis la pile, on peut aussi lire une chaîne de caractères rangée plus loin : c’est ainsi qu’on retrouve, sous GDB, le texte d’un argument passé au programme.",
      "Certains programmes coopèrent avec le débogueur : ils contiennent une instruction d’arrêt volontaire (un point d’arrêt logiciel) qui rend la main à GDB quand l’exécution l’atteint. Dans ce cas, c’est la commande run — lancer normalement — qui convient, plutôt que starti : on laisse le programme courir jusqu’à son point d’arrêt, avec les registres préparés comme il faut avant de partir.",
      "GDB contrôle aussi l’environnement d’exécution : run suivi d’arguments lance le programme avec ces arguments, comme en ligne de commande ; et une redirection d’entrée permet de nourrir le programme depuis un fichier plutôt qu’au clavier, toujours depuis le débogueur. Maîtriser ces réglages, c’est reproduire en laboratoire n’importe quelle situation d’exécution."],
    term:"(gdb) x/d $rsp\n(gdb) run < saisie.txt\n<span class=\"tdim\">x : examiner la mémoire (ici en décimal) · run < : nourrir le programme depuis un fichier.</span>",
    ex:{ type:"qcm", q:"Un programme contient son propre point d’arrêt et attend que tu prépares un registre avant de le lancer. Quelle conduite convient ?",
      opts:["starti, puis avancer instruction par instruction jusqu’au bout", "Préparer le registre avec set, puis run : le programme court jusqu’à son point d’arrêt", "Quitter GDB, ce cas ne se débogue pas"], ok:1 },
    why:"Quand le programme coopère, inutile de marcher au pas depuis la première instruction : on règle l’état, on lance avec run, et l’arrêt intégré fait le rendez-vous. starti reste l’outil de l’observation fine ; run, celui de la rencontre planifiée." },
  { id:"C101-11", mod:"Output and Input", t:"Écrire et lire : write, read et les descripteurs", sub:"Tout échange passe par un numéro de canal : 0 pour lire, 1 pour écrire, 2 pour alerter.",
    read:["Un programme communique par des canaux numérotés, les descripteurs de fichiers : 0 est l’entrée standard (le clavier, par défaut), 1 la sortie standard (l’écran), 2 la sortie d’erreur. Le syscall write, numéro 1, écrit sur un canal : rdi dit lequel, rsi donne l’adresse des octets, rdx leur nombre. Chaîner write puis exit produit le premier programme qui « parle ».",
      "Dans l’autre sens, le syscall read, numéro 0, lit depuis un canal vers une adresse mémoire — par exemple vers la pile, zone de travail toute trouvée — et rend dans rax le nombre d’octets réellement lus. Cette valeur de retour est précieuse : elle dit la longueur vraie des données reçues, qui peut être moindre que la taille demandée.",
      "D’où un enchaînement que tu reverras partout : lire, garder la longueur rendue (en la recopiant avant qu’un autre syscall n’écrase rax), puis écrire exactement cette longueur-là. Écrire « ce qu’on a demandé » au lieu de « ce qu’on a reçu » est une source classique de données parasites."],
    term:"write : rax = 1 · rdi = canal · rsi = adresse · rdx = nombre d’octets\nread : rax = 0 · retour dans rax = octets réellement lus\n<span class=\"tdim\">Canaux : 0 entrée · 1 sortie · 2 erreurs.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre un écho fidèle : lire des données, puis réécrire exactement ce qui a été lu :",
      items:["Appeler read vers un tampon et récupérer le nombre d’octets réellement lus dans rax", "Recopier cette longueur dans rdx avant qu’un autre syscall n’écrase rax", "Régler write : canal 1, adresse du tampon", "Appeler write, puis terminer proprement"],
      disp:[1,3,0,2] },
    why:"La longueur vraie vient de la valeur de retour de read — pas de ta demande. La recopier à temps, avant le syscall suivant, est LE réflexe de ce module : rax sert à tout, donc tout ce qu’il contient d’utile doit être mis à l’abri immédiatement." },
  { id:"C101-12", mod:"Output and Input", t:"Ouvrir un fichier et placer une chaîne en mémoire", sub:"open rend un nouveau canal ; une chaîne peut se construire octet par octet, ou se charger par adresse relative.",
    read:["Pour lire un fichier qui n’est pas déjà un canal, il faut l’ouvrir : le syscall open, numéro 2, prend dans rdi un pointeur vers le nom du fichier et dans rsi le mode (0 pour lecture seule). Il rend dans rax un nouveau descripteur — 3 ou plus, les trois premiers étant pris par les canaux standards. Un échec rend −1 : vérifier cette valeur évite de lire dans le vide. strace, vu plus haut, est l’outil idéal pour voir un open échouer.",
      "Reste un problème pratique : d’où vient le nom du fichier ? Une technique le construit directement sur la pile, octet par octet : on écrit chaque caractère à sa position, puis un octet nul final — car les chaînes, en bas niveau, se terminent par un zéro qui n’est pas le caractère « 0 ». Fastidieux, mais sans aucune donnée externe.",
      "La technique moderne range la chaîne dans le programme lui-même, après le code, et charge son adresse par adressage relatif à l’instruction en cours : lea calcule l’adresse (« l’endroit où vit la chaîne »), là où un mov chargerait les octets de la chaîne eux-mêmes. C’est la forme qu’exigent les exécutables modernes, dont l’adresse de chargement varie."],
    term:"lea rdi, [rip+nom]\n<span class=\"tdim\">lea : charger l’ADRESSE de la chaîne · mov aurait chargé ses premiers octets, ce n’est pas la même chose.</span>",
    ex:{ type:"qcm", q:"Pourquoi utiliser lea, et non mov, pour passer le nom d’un fichier rangé dans le programme ?",
      opts:["Parce que mov ne sait pas copier de nombres", "Parce qu’il faut l’adresse de la chaîne : lea la calcule relativement à l’instruction en cours, là où mov chargerait le contenu de la chaîne", "Parce que lea est plus rapide à taper"], ok:1 },
    why:"open attend un pointeur, pas des octets : adresse contre contenu, encore — le thème du module mémoire, appliqué aux chaînes. Et l’adressage relatif au compteur d’instructions rend le programme indépendant de son adresse de chargement : indispensable dans les exécutables actuels." },
  { id:"C101-13", mod:"Control Flow", t:"Comparer et décider : cmp, les drapeaux et les sauts", sub:"cmp pose une question, le Zero Flag garde la réponse, je et jne choisissent la route.",
    read:["Jusqu’ici, tes programmes avançaient en ligne droite. Le flux de contrôle casse cette ligne : comparer, puis sauter ailleurs selon le résultat. L’instruction cmp compare deux valeurs en effectuant une soustraction… sans garder le résultat. Ce qu’elle garde, ce sont des drapeaux : de petits bits d’état, dont le Zero Flag (ZF), qui vaut 1 exactement quand les deux valeurs étaient égales.",
      "Une instruction comme setz transforme le drapeau en donnée : elle écrit 1 dans un registre si ZF est levé, 0 sinon — parfait pour rendre un verdict en code de sortie (qui ne retient, rappelle-toi, que les 8 bits bas). Plus direct encore : les sauts conditionnels je et jne bifurquent selon ZF, vers des étiquettes (labels) qui nomment les endroits du code. Si la condition n’est pas remplie, l’exécution continue simplement à la suite : la branche non prise n’a pas besoin d’être sautée, elle est le chemin droit.",
      "Avec ces briques, un programme vérifie une condition — par exemple qu’un octet d’argument est le caractère attendu — et sort avec 0 en cas de succès, 1 en cas d’échec. Comparer une chaîne entière n’est que la répétition du même geste, octet par octet, jusqu’au premier écart ou au terminateur."],
    term:"cmp BYTE PTR [rax], 'p'\njne echec\n<span class=\"tdim\">Comparer un octet au caractère « p » · Sauter à l’étiquette « echec » si ce n’est pas égal.</span>",
    ex:{ type:"qcm", q:"Que reste-t-il après l’exécution d’un cmp entre deux valeurs égales ?",
      opts:["Le résultat de la soustraction, rangé dans un registre", "Le Zero Flag est levé (ZF = 1), et aucun résultat n’est rangé : cmp ne garde que les drapeaux", "Le programme saute automatiquement à la fin"], ok:1 },
    why:"cmp est une question, pas un calcul : il jette le résultat et ne conserve que l’état des drapeaux. Tout le flux conditionnel repose sur cette séparation — une instruction pose la question, les suivantes (setz, je, jne) exploitent la réponse." },
  { id:"C101-14", mod:"Control Flow", t:"Boucles : reconnaître le motif, puis l’écrire", sub:"Un saut en arrière est une boucle ; une boucle tient par un état et une progression.",
    read:["Le saut inconditionnel jmp va toujours à son étiquette. Dirigé vers l’arrière, il crée une boucle : le même bloc d’instructions s’exécute en rond. En lisant un programme inconnu, repérer un saut arrière est donc le premier indice d’une boucle — par exemple une vérification qui compare un mot secret caractère par caractère, en échouant dès le premier écart et en réussissant quand arrive le terminateur nul.",
      "Écrire une boucle demande deux disciplines : un état (où en suis-je ? — un pointeur qui avance, un compteur) et une progression (chaque tour doit rapprocher de la fin). Le modèle du module : mesurer la longueur d’une chaîne en avançant octet par octet jusqu’au terminateur nul, le compteur devenant le résultat.",
      "Une variante spectaculaire mérite un détour : la table de saut. Au lieu d’enchaîner les comparaisons, le programme range des centaines d’adresses dans un tableau et indexe directement la bonne avec la valeur d’entrée — un aiguillage en un seul chargement. Lire une telle table demande les outils d’examen mémoire de GDB : l’unité de lecture choisie change ce qu’on voit."],
    term:"boucle:\n  … lire l’octet courant …\n  cmp octet, 0\n  jne boucle\n<span class=\"tdim\">Tant que l’octet n’est pas le terminateur nul, on recommence : état + progression.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la boucle qui mesure la longueur d’une chaîne :",
      items:["Initialiser un pointeur au début de la chaîne et un compteur à zéro", "Lire l’octet pointé", "Si c’est le terminateur nul, terminer : le compteur est la longueur", "Sinon, avancer le pointeur, incrémenter le compteur et recommencer"],
      disp:[2,0,3,1] },
    why:"État, test, progression : il manque un seul de ces trois ingrédients et la boucle ne termine jamais — ou termine sans avoir rien mesuré. En analyse comme en écriture, vérifier ces trois points dans l’ordre dépanne presque toutes les boucles." },
  { id:"C101-15", mod:"Control Flow", t:"Appeler et revenir : fonctions, bibliothèques et registres à préserver", sub:"call pousse l’adresse de retour, ret la dépile — et certains registres ont des propriétaires.",
    read:["Une fonction est un morceau de code qu’on appelle et qui rend la main. call fait deux choses : il pousse sur la pile l’adresse de l’instruction suivante (l’adresse de retour), puis saute vers la fonction. ret fait l’inverse : il dépile cette adresse et y saute. La valeur rendue par la fonction voyage, par convention, dans rax.",
      "Le code réutilisable se range dans des bibliothèques partagées : des fichiers chargés au besoin par le programme principal, qui y appelle des fonctions écrites ailleurs — par exemple une petite fonction qui reçoit un tampon et une longueur, réarrange les registres et effectue l’écriture à ta place. Un pointeur de fonction n’est rien d’autre qu’une adresse dans un registre : appeler via ce registre lance la fonction désignée. Si ce registre sert aussi au premier argument, on déplace d’abord le pointeur dans un registre libre pour libérer la place de l’argument.",
      "Dernière convention, capitale : les registres se partagent en deux familles. Les caller-saved peuvent être écrasés par la fonction appelée : si leur contenu compte encore, l’appelant les met à l’abri (push) avant l’appel et les récupère (pop) après. Les callee-saved doivent au contraire être rendus intacts par la fonction appelée : elle les sauvegarde à l’entrée si elle veut s’en servir, et les restaure avant ret."],
    term:"call fonction   ; pousse l’adresse de retour, puis saute\nret             ; dépile l’adresse de retour et y revient\n<span class=\"tdim\">Valeur de retour : dans rax · caller-saved : à protéger par l’appelant · callee-saved : à restaurer par l’appelé.</span>",
    ex:{ type:"qcm", q:"Une fonction appelée a besoin d’utiliser un registre callee-saved. Quelle est sa responsabilité ?",
      opts:["Aucune : elle peut l’écraser librement", "Le sauvegarder à l’entrée (push) et le restaurer avant de revenir (pop), pour le rendre intact à son appelant", "Le mettre à zéro avant de revenir"], ok:1 },
    why:"Callee-saved signifie « l’appelé garantit » : qui s’en sert le met à l’abri et le rend comme trouvé. L’inverse vaut pour les caller-saved : c’est l’appelant qui protège ce qui lui tient à cœur. Ces conventions sont le contrat social qui permet à du code écrit par des inconnus de s’appeler sans se détruire." },
  { id:"C101-16", mod:"Endian Escapades", t:"Little-endian : l’octet faible d’abord", sub:"En mémoire, les octets d’un nombre se rangent du plus faible au plus fort — les dumps semblent donc inversés.",
    read:["Les processeurs x86 rangent les nombres en mémoire en little-endian : l’octet de poids faible — celui des unités — vient en premier, à l’adresse la plus basse. La valeur 0x1234 occupe ainsi les octets 34 puis 12. Deux raisons à ce choix : l’arithmétique commence naturellement par le petit bout, et lire seulement les premiers octets d’une valeur depuis son adresse donne directement sa partie basse.",
      "Conséquence visuelle célèbre : quand des octets de texte sont chargés d’un bloc dans un registre, l’affichage hexadécimal du registre semble présenter les caractères à l’envers. Les octets n’ont pas bougé en mémoire : c’est la lecture par paquets qui donne cette impression. La taille du paquet a ses noms : octet (8 bits), word (16), dword (32), qword (64) — avec leurs registres associés, du plus petit au plus grand.",
      "Le boutisme se corrige donc à la taille de la lecture : on inverse les octets À L’INTÉRIEUR de chaque unité lue, en gardant les unités dans l’ordre des adresses — jamais en inversant tout le bloc d’un coup, sauf si l’unité faisait la taille du bloc. Le même raisonnement s’applique champ par champ dans une structure de données mêlant plusieurs tailles, chaque champ vivant à son décalage propre. Et pour les valeurs signées, l’extension de signe copie le bit du haut dans les bits ajoutés quand on élargit une petite valeur dans un grand registre."],
    term:"Valeur 0x11223344 rangée en mémoire : 44 33 22 11\n<span class=\"tdim\">L’octet faible (44) à l’adresse la plus basse · L’ordre des unités reste celui des adresses.</span>",
    ex:{ type:"qcm", q:"En mémoire little-endian, comment se range la valeur 0x1234 ?",
      opts:["Octets 12 puis 34, comme on l’écrit", "Octets 34 puis 12 : l’octet faible d’abord", "Cela dépend du programme qui l’a écrite"], ok:1 },
    why:"Little-endian = petit bout premier : l’octet de poids faible occupe l’adresse la plus basse. C’est un fait du matériel x86, pas un choix du programme — et c’est ce qui explique les « inversions » apparentes dans chaque dump mémoire que tu croiseras." },
  { id:"C101-17", mod:"Assembly Assortment", t:"Calculer avec des bits : opérations et masques", sub:"Chaque opération a son inverse ; and ne garde que les bits qu’on lui désigne.",
    read:["Ce module élargit le vocabulaire des instructions en les lisant à rebours : comprendre l’effet d’une opération, c’est souvent savoir l’inverser. Ce qu’une addition a ajouté se défait par une soustraction de même valeur ; ce qu’une soustraction a retiré se rajoute. L’opération xor, elle, est sa propre inverse : appliquer deux fois le même xor avec la même clé redonne la valeur de départ.",
      "L’opération and sert de filtre : combinée à un masque, elle ne conserve que les bits désignés par le masque et force les autres à zéro. Avec le masque 1, elle isole le bit de poids faible — celui qui dit si un nombre est pair ou impair. Avec le masque 0xFF, elle ne garde que l’octet bas d’une valeur : une extraction propre, très utilisée.",
      "Ces instructions vivent aussi en fonctions réutilisables rangées dans des bibliothèques partagées, exportées sous un nom que d’autres programmes appellent : recevoir une valeur dans rdi, appliquer l’opération, rendre le résultat dans rax. Simple — à condition de respecter les conventions d’appel de la leçon C101-15."],
    term:"and rax, 0xFF\n<span class=\"tdim\">Masque 0xFF : ne garder que l’octet bas, tout le reste passe à zéro.</span>",
    ex:{ type:"qcm", q:"Un programme a transformé une valeur par « xor avec 0x2a ». Comment retrouver la valeur d’origine ?",
      opts:["En soustrayant 0x2a", "En appliquant à nouveau « xor avec 0x2a » : xor est son propre inverse", "C’est impossible sans le code source"], ok:1 },
    why:"xor appliqué deux fois avec la même clé s’annule : chaque bit basculé deux fois revient à son état. C’est pour ça que xor apparaît partout — filtrage, comparaisons, et aussi dans des chiffrements faibles que ce genre d’annulation rend transparents." },
  { id:"C101-18", mod:"Assembly Assortment", t:"Casse, décalages et données rangées à part", sub:"Un seul bit sépare « A » de « a » ; décaler, c’est multiplier ou diviser par des puissances de deux.",
    read:["En ASCII, une lettre majuscule et sa minuscule ne diffèrent que par un seul bit : celui de valeur 0x20. Forcer ce bit à 1 (or avec 0x20) passe en minuscule ; le forcer à 0 (and avec 0xDF, le masque inverse) passe en majuscule ; l’inverser (xor avec 0x20) échange la casse. Appliquées en boucle, octet par octet jusqu’au terminateur nul, ces opérations transforment des chaînes entières en place.",
      "Les décalages déplacent tous les bits d’un cran ou plus : décaler à gauche de n multiplie par 2 puissance n (décaler de 4, c’est multiplier par 16) ; décaler à droite de n divise par 2 puissance n, en remplissant de zéros — pour les valeurs non signées. Combiné à un masque, le décalage extrait un octet précis au milieu d’une valeur.",
      "Enfin, toutes les données d’un programme ne vivent pas dans ses instructions : les constantes — textes, tables — sont souvent rangées dans une section de données en lecture seule. En inspectant un binaire, on peut donc y retrouver des textes entiers sans désassembler le code, avec les outils d’extraction de chaînes ou en examinant les sections du fichier. Moralité d’analyste : le code dit ce que le programme fait ; ses données disent souvent ce qu’il cache."],
    term:"shl rax, 4   ; × 16\nshr rax, 8   ; ÷ 256 (non signé)\n<span class=\"tdim\">Décaler de n = multiplier ou diviser par 2 puissance n.</span>",
    ex:{ type:"qcm", q:"Que fait « or avec 0x20 » appliqué au code ASCII d’une lettre majuscule ?",
      opts:["Il transforme la lettre en chiffre", "Il force à 1 le bit de casse : la lettre devient minuscule", "Il inverse tous les bits de la lettre"], ok:1 },
    why:"Le bit 0x20 est LE bit de casse en ASCII : le mettre à 1 donne la minuscule, l’effacer donne la majuscule, l’inverser échange. Une seule opération logique remplace ainsi un tableau de correspondance de 26 lettres — l’élégance du bas niveau." },
  { id:"C101-19", mod:"The Stack, Revisited", t:"La pile grandit vers le bas : cadres et données périmées", sub:"push fait reculer rsp, pop le fait avancer — et ce qui quitte la pile n’est pas effacé.",
    read:["Retour sur la pile, en profondeur. Elle croît vers les adresses basses : push équivaut à « reculer rsp de 8, puis ranger la valeur », et pop à « charger la valeur, puis avancer rsp de 8 ». Un appel de fonction pousse l’adresse de retour ; le cadre de l’appelé — sa zone de travail sur la pile — vit donc à des adresses plus basses que celui de l’appelant, dont les variables locales se lisent à des décalages positifs au-dessus de rsp.",
      "Fait troublant et capital : quand une fonction revient, ses octets ne sont pas effacés. Ils restent sur la pile, périmés, jusqu’à ce qu’un autre appel les écrase. Une fonction suivante peut ainsi relire — volontairement ou par erreur — les restes de la précédente. Côté sécurité, c’est une source de fuites d’informations ; côté débogage, une source de valeurs « fantômes » qui semblent venir de nulle part.",
      "Pour son propre travail, une fonction réserve son cadre en reculant rsp de la taille voulue : ces octets deviennent son espace privé — assez grand, par exemple, pour une table de 256 cases indexées par les valeurs d’octets. Règle d’or avant de revenir : restaurer rsp exactement (avancer d’autant) avant ret, sinon ret dépilera n’importe quoi comme adresse de retour."],
    term:"sub rsp, 256   ; réserver 256 octets de cadre\n… travail …\nadd rsp, 256   ; les rendre AVANT ret\n<span class=\"tdim\">Réserver et rendre : les deux moitiés d’un même geste.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la vie d’un cadre de pile bien tenu :",
      items:["Réserver l’espace avec sub rsp", "Travailler dans l’espace réservé (variables, tables)", "Rendre l’espace avec add rsp, de la même taille", "Revenir avec ret, qui dépile la vraie adresse de retour"],
      disp:[1,3,0,2] },
    why:"Oublier le add avant ret est une des pannes les plus nettes du bas niveau : ret dépile alors un octet de tes données comme si c’était une adresse, et le programme saute n’importe où. Réserver et rendre sont indissociables — comme ouvrir et fermer une parenthèse." },
  { id:"C101-20", mod:"The Stack, Revisited", t:"L’environnement sur la pile, et l’art d’aligner les adresses", sub:"Après les arguments viennent les variables d’environnement — leur taille déplace tout le reste.",
    read:["Après argc, les pointeurs d’arguments et un pointeur nul de fin, le noyau range sur la pile un second tableau : les pointeurs vers les variables d’environnement, des chaînes de la forme NOM=VALEUR, lui aussi terminé par un pointeur nul. Un programme peut donc atteindre, à un décalage fixe au-delà des arguments, une variable précise de son environnement de lancement.",
      "Subtilité du module : le noyau remplit la pile à rebours depuis une origine haute. La taille totale des chaînes d’environnement et d’arguments influence donc les adresses absolues où les choses se rangent : ajouter des octets d’environnement décale les adresses vers le bas. Contrôler l’environnement — partir d’un environnement vide, puis ajouter exactement les variables voulues, en comptant le nom, le « = », la valeur et le zéro final — devient un instrument de précision pour placer une adresse où on la veut.",
      "Et le débogueur complique tout : GDB lance le programme avec son propre environnement, différent du shell. Une adresse mesurée sous GDB n’est donc pas celle de l’exécution directe. L’alignement rigoureux consiste à mesurer l’écart, puis à ajuster l’environnement du lancement réel — parfois octet par octet — jusqu’à faire coïncider les deux mondes."],
    term:"$ env -i ./prog\n$ env -i NOM=valeur ./prog\n<span class=\"tdim\">env -i : partir d’un environnement vide, puis ne mettre que ce qu’on choisit.</span>",
    ex:{ type:"qcm", q:"Pourquoi l’adresse d’un argument n’est-elle pas la même sous GDB et en lancement direct ?",
      opts:["Parce que GDB réécrit le programme", "Parce que GDB lance le programme avec un environnement différent, et que la taille de l’environnement déplace les adresses sur la pile", "Parce que les adresses changent au hasard à chaque lancement, sans cause"], ok:1 },
    why:"La pile de départ est construite à rebours : tout octet d’environnement en plus ou en moins déplace ce qui suit. GDB ajoutant ses propres variables, ses adresses sont les siennes — les mesurer sans comprendre cet écart fait courir après un fantôme." },
  { id:"C101-21", mod:"Numbers as Strings", t:"atoi : transformer du texte en nombre", sub:"Un chiffre vaut son code moins celui de « 0 » ; le nombre se construit par × 10 successifs.",
    read:["Les humains écrivent les nombres en texte ; les processeurs calculent sur des valeurs. Convertir le texte en nombre — la fonction atoi — est le premier vrai algorithme du dojo. Brique de base : un caractère chiffre vaut sa position depuis « 0 » — soustraire le code de « 0 » au code du caractère donne le chiffre, de 0 à 9.",
      "Pour plusieurs chiffres, la boucle fait le travail : total = total × 10 + chiffre courant, en avançant caractère par caractère. La fin du nombre n’est pas un caractère spécial « fin » : c’est le terminateur nul de la chaîne, l’octet zéro — à ne pas confondre avec le caractère « 0 », qui est un chiffre comme les autres.",
      "Deux raffinements rendent la fonction honnête : un signe « − » en première position se note et s’applique à la fin, en niant le total ; et la lecture s’arrête au premier caractère qui n’est pas un chiffre — on le détecte en testant si (caractère − « 0 ») tombe dans l’intervalle 0 à 9, avec une comparaison non signée qui rejette d’un coup les deux côtés."],
    term:"total = 0\nboucle : total = total × 10 + (caractère − '0')\n<span class=\"tdim\">« 4 » puis « 2 » : 0×10+4 = 4, puis 4×10+2 = 42.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la conversion d’un texte de chiffres en nombre :",
      items:["Partir d’un total à zéro et noter un éventuel signe « − » initial", "Lire le caractère courant et en faire un chiffre (moins « 0 »)", "Faire total = total × 10 + chiffre, puis avancer d’un caractère", "S’arrêter au terminateur ou au premier non-chiffre, puis appliquer le signe"],
      disp:[2,0,3,1] },
    why:"× 10 puis + chiffre, en boucle : cet algorithme minuscule est celui de toutes les saisies numériques, partout. Ses deux pièges sont symétriques : confondre le terminateur nul avec le caractère « 0 », et oublier que le signe se traite à part, avant ou après la boucle — jamais dedans." },
  { id:"C101-22", mod:"Numbers as Strings", t:"itoa : transformer un nombre en texte", sub:"Diviser par 10 donne les chiffres… à l’envers ; la pile les remet dans l’ordre.",
    read:["Le trajet inverse — itoa, du nombre vers le texte — repose sur la division. Diviser la valeur par 10 donne un quotient (la suite du nombre) et un reste (le dernier chiffre). L’instruction de division travaille sur un couple de registres et exige de préparer le registre haut à zéro avant de diviser ; le diviseur, lui, va dans un registre libre. Chaque reste, plus le code de « 0 », devient un caractère.",
      "Problème d’ordre : les chiffres sortent à l’envers, unités d’abord. Deux solutions classiques : les empiler au fur et à mesure puis les dépiler (la pile, dernier entré premier sorti, les rend dans le bon ordre), ou écrire le texte à rebours dans le tampon. Et les cas limites comptent : un quotient des dizaines nul ne doit pas produire un zéro initial parasite — sauf pour la valeur zéro elle-même, qui s’écrit bien « 0 », en un seul caractère.",
      "Les négatifs se traitent comme dans atoi, en miroir : retenir le signe, écrire « − » en premier, avancer la position d’écriture, et convertir la valeur rendue positive. La longueur rendue par la fonction compte tout, signe compris : c’est elle que l’appelant utilisera pour écrire le texte."],
    term:"123 ÷ 10 → quotient 12, reste 3\n12 ÷ 10 → quotient 1, reste 2\n<span class=\"tdim\">Les restes sortent 3, 2, 1 : à remettre dans l’ordre 1, 2, 3.</span>",
    ex:{ type:"qcm", q:"Pourquoi les chiffres produits par divisions successives doivent-ils être réordonnés ?",
      opts:["Parce que la division rend les chiffres des unités d’abord : ils sortent à l’envers de l’ordre d’écriture", "Parce que le tampon inverse automatiquement son contenu", "Parce que les restes sont toujours faux du premier coup"], ok:0 },
    why:"Le reste d’une division par 10 est le chiffre le plus à droite : l’algorithme produit donc le texte de droite à gauche. La pile — ou une écriture à rebours — n’est pas un raffinement : c’est la moitié de l’algorithme." },
  { id:"C101-23", mod:"Numbers as Strings", t:"Une calculatrice en assembleur", sub:"atoi, une opération, itoa : la boucle est bouclée, avec les opérateurs unaires en prime.",
    read:["Assemble maintenant les briques : un programme complet qui lit ses arguments sur la pile de départ, convertit les opérandes avec atoi, applique l’opération demandée, convertit le résultat avec itoa dans un tampon de pile, l’écrit sur la sortie et termine proprement. L’opérateur se lit dans l’argument du milieu : son premier caractère décide de la branche — addition, soustraction, multiplication.",
      "La famille s’élargit aux opérateurs bit à bit rencontrés dans Assembly Assortment : xor, or et and s’ajoutent comme des branches de plus, avec les mêmes opérandes convertis. Attention au shell : plusieurs de ces symboles sont spéciaux pour lui (l’étoile, la barre verticale, l’esperluette) — les protéger par des guillemets dans la ligne de commande fait partie du métier.",
      "Dernier étage : les opérateurs unaires, qui n’ont qu’un opérande. On les distingue des binaires en comptant les arguments : avec un argument de moins, l’opérateur se lit à une autre position. La négation change le signe ; l’opérateur « ~ » inverse tous les bits, ce qui, en complément à deux, vaut exactement « −x − 1 ». La calculatrice complète tient alors en un seul programme — construit uniquement avec les briques de ce dojo."],
    term:"$ ./calc 6 '*' 7\n42\n<span class=\"tdim\">Les guillemets protègent l’opérateur du shell · Dedans : atoi, opération, itoa.</span>",
    ex:{ type:"qcm", q:"Comment la calculatrice distingue-t-elle un appel binaire (deux opérandes) d’un appel unaire (un seul) ?",
      opts:["Elle essaie les deux et garde celui qui marche", "Elle compte les arguments (argc) : le nombre d’arguments dit où se trouvent l’opérateur et les opérandes", "L’opérateur unaire s’écrit toujours en majuscules"], ok:1 },
    why:"argc, lu sur la pile de départ dès le module The Stack, est l’aiguillage : 4 éléments annoncés pour un calcul binaire, 3 pour un unaire. Tout se recoupe — c’est la signature des programmes bien construits : chaque notion ancienne devient un outil du programme final." },
  { id:"C101-24", mod:"Numbers as Strings", t:"Un mini printf : format, échappements et marqueurs", sub:"Parcourir un texte, y reconnaître les séquences spéciales, et y insérer des valeurs converties.",
    read:["Le couronnement du module : une fonction d’affichage à format, comme le printf des langages. On lui donne une chaîne de format et des arguments ; elle parcourt le format caractère par caractère et écrit le texte ordinaire tel quel, jusqu’au terminateur. Toute la difficulté tient dans les séquences spéciales, introduites par un caractère d’échappement.",
      "Premier jeu de séquences : les antislashs. Un « \\n » dans le format devient un vrai saut de ligne (l’octet 0x0a) ; un double antislash donne un antislash littéral ; et le double pour cent, vu juste après, donne un pour cent littéral. Dans tous les cas, on consomme deux caractères du format pour produire un seul caractère — ou une valeur — en sortie.",
      "Deuxième jeu : les marqueurs pour cent. « %d » insère l’argument suivant, converti de texte en nombre puis réécrit en décimal signé avec les atoi et itoa du module ; chaque marqueur consomme l’argument suivant, dans l’ordre — il faut donc suivre DEUX positions : où on en est dans le format, et quel est le prochain argument. « %s » insère l’argument suivant tel quel, sans interpréter ses caractères spéciaux. Dernière séquence : « \\x » suivi de deux chiffres hexadécimaux produit l’octet correspondant — chaque chiffre devient un nibble, et les deux se combinent par (premier × 16) + second."],
    term:"format : « total %d \\n »\n<span class=\"tdim\">%d : insérer le nombre converti · \\n : un vrai saut de ligne · Le reste : du texte ordinaire.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre le traitement d’un marqueur « %d » pendant le balayage du format :",
      items:["Repérer le « % » et lire le caractère suivant : c’est un « d »", "Prendre la chaîne de l’argument suivant, dans l’ordre des arguments", "La convertir en nombre (atoi), puis le nombre en texte signé (itoa)", "Écrire ces chiffres, puis reprendre le balayage du format juste après le marqueur"],
      disp:[1,3,0,2] },
    why:"Un printf miniature n’est qu’un balayage discipliné : texte ordinaire copié, séquences consommées par paires, arguments consommés dans l’ordre. Les deux compteurs — position dans le format, prochain argument — sont l’état de la machine ; les perdre produit les sorties décalées que tout programmeur a croisées un jour." },
  { id:"C101-25", mod:"Debugging Refresher", t:"GDB, le retour : inspecter, arrêter, scripter, modifier", sub:"Le module de révision du débogage — avec deux défis du site qui restent verrouillés, et signalés comme tels.",
    read:["Ce module repasse l’outil GDB en revue, sous forme guidée : un programme d’entraînement lance le débogueur et te fait pratiquer commande par commande. Au menu : afficher tous les registres d’un coup, lire un registre en décimal ou en hexadécimal, et examiner la mémoire avec la commande x dans ses variantes — nombre d’unités, taille d’unité (octet, demi-mot, mot, géant), format (décimal, hexadécimal, chaîne, instructions). Désassembler une fonction nommée et afficher les instructions autour du point courant font partie du même geste d’orientation.",
      "Vient ensuite le contrôle du temps : avancer d’une instruction, avancer en sautant les appels, laisser une fonction se terminer, poser un point d’arrêt à une adresse précise et continuer jusqu’à lui, tout en gardant un affichage permanent de la zone surveillée. Un mode texte affiche registres et code en permanence. Et GDB se scripte : des commandes peuvent être passées au lancement, rangées dans un fichier de commandes, ou placées dans un fichier d’initialisation personnel que GDB exécute à chaque démarrage — par exemple pour toujours travailler en syntaxe Intel. Les points d’arrêt eux-mêmes peuvent porter des commandes automatiques, silencieuses ou non, qui lisent des valeurs à chaque passage.",
      "Enfin, modifier l’état en cours d’exécution : la commande set réécrit un registre, ou une case mémoire à une adresse précise, avec la taille voulue. C’est l’outil qui permet de tester « et si cette valeur était autre ? » sans recompiler. Honnêteté de couverture : le module compte deux défis de plus sur le site — annoncés sous les titres « Modifying Execution » et « Broken Functions » — mais ils sont VERROUILLÉS tant que leurs prérequis ne sont pas résolus là-bas : leur contenu n’a pas pu être récupéré, ils sont donc signalés ici comme non disponibles, sans rien inventer à leur place."],
    term:"(gdb) info registers\n(gdb) x/16gx $rsp\n(gdb) break *ADRESSE\n<span class=\"tdim\">Inspecter les registres · Examiner 16 mots géants de la pile · S’arrêter à une adresse.</span>",
    ex:{ type:"qcm", q:"Quelle affirmation décrit correctement les deux derniers défis de ce module sur le site ?",
      opts:["Ils sont résumés dans cette leçon comme les autres", "Ils sont verrouillés tant que leurs prérequis ne sont pas résolus : leur contenu n’a pas pu être récupéré, et cette leçon le signale sans rien inventer", "Ils ont été retirés du site et n’existent plus"], ok:1 },
    why:"Dire ce qu’on ne sait pas fait partie du travail d’analyste : deux défis existent, leurs titres sont annoncés, mais leur contenu est derrière un verrou de progression. Les signaler comme non disponibles — plutôt que d’inventer une leçon plausible — est la seule conduite honnête, ici comme dans un rapport." },
  { id:"C101-26", mod:"Building a Web Server", t:"Ouvrir une ligne : socket, bind, listen, accept", sub:"Un serveur est un programme qui attend : quatre appels système montent la ligne d’écoute.",
    read:["Le projet final du dojo assemble tout : construire un serveur web, uniquement avec des appels système. Un serveur commence par créer un point de communication, une socket : l’appel socket, avec les constantes qui désignent une connexion TCP sur IPv4, rend un descripteur — un canal de plus, comme ceux des fichiers.",
      "Il faut ensuite attacher cette socket à une adresse et un port : c’est bind, qui reçoit un pointeur vers une petite structure construite sur la pile — seize octets qui décrivent la famille d’adresses, le port (rangé en ordre réseau, c’est-à-dire gros boutien, contrairement au little-endian de la machine), l’adresse d’écoute et un remplissage de zéros. Les constantes de ces champs ne se devinent pas : on les retrouve dans la documentation et les en-têtes du système.",
      "listen transforme alors la socket en ligne d’attente passive, avec le nombre maximal de connexions en file. Enfin, accept bloque jusqu’à ce qu’un client se présente : il rend un NOUVEAU descripteur, dédié à ce client, et remplit au passage une structure avec les coordonnées du visiteur. La socket d’écoute, elle, reste libre pour le client suivant : une ligne d’accueil, des conversations séparées."],
    term:"socket → bind → listen → accept\n<span class=\"tdim\">Créer le point · L’attacher à un port · Ouvrir la file · Accueillir un client (nouveau descripteur).</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la montée d’une ligne d’écoute :",
      items:["Créer la socket avec l’appel socket", "L’attacher à une adresse et un port avec bind", "La passer en écoute passive avec listen", "Accueillir un client avec accept, qui rend un descripteur dédié"],
      disp:[2,0,3,1] },
    why:"Créer, attacher, écouter, accueillir : chaque étape prépare la suivante, et l’ordre ne pardonne pas — accept avant listen n’a aucun sens. Note le détail qui relie tout le dojo : le port voyage en ordre réseau, gros boutien, dans un monde de machine little-endian — le module Endian Escapades, en situation réelle." },
  { id:"C101-27", mod:"Building a Web Server", t:"Répondre en HTTP et servir tout le monde", sub:"Une réponse fixe d’abord, puis des fichiers demandés, puis plusieurs clients à la fois grâce à fork.",
    read:["La première réponse tient en une ligne de texte : la version du protocole, le code 200 qui dit « d’accord », et une ligne vide qui sépare les en-têtes du corps — envoyée avec write sur le descripteur du client. C’est une réponse statique : la même pour tous. La réponse dynamique lit d’abord la requête du client, en extrait le chemin demandé dans la ligne de requête, ouvre le fichier correspondant — avec les open et read des modules précédents — et renvoie son contenu.",
      "Un serveur utile ne s’arrête pas après un client : il boucle. Accepter, lire, répondre, fermer le descripteur du client, puis revenir à accept — cette version itérative sert les requêtes les unes après les autres. Pour servir en parallèle, le programme se dédouble avec l’appel fork : le processus enfant prend la conversation en charge pendant que le parent retourne immédiatement accueillir le client suivant. C’est le modèle des vrais serveurs.",
      "Reste le sens inverse : recevoir des données. Une requête d’envoi (POST) transporte un corps après ses en-têtes, dont la longueur se lit dans un en-tête dédié — ou se déduit de ce que read a rapporté. Le serveur écrit alors ce corps dans le fichier nommé par le chemin, et répond son accord. Le serveur complet route enfin selon les premiers caractères de la requête : lecture ou envoi, chaque conversation est confiée à un enfant, et la ligne d’accueil ne se bloque jamais. Tu viens de reconstruire, en assembleur, ce que Playing With Programs faisait dialoguer de l’extérieur."],
    term:"HTTP/1.0 200 OK, ligne vide, puis le contenu\n<span class=\"tdim\">Statique : toujours la même réponse · Dynamique : le chemin de la requête choisit le fichier · fork : un enfant par client.</span>",
    ex:{ type:"qcm", q:"À quoi sert fork dans le serveur concurrent ?",
      opts:["À fermer le descripteur du client plus vite", "À dédoubler le programme : l’enfant sert le client pendant que le parent retourne accueillir le suivant", "À traduire la requête HTTP en assembleur"], ok:1 },
    why:"Sans fork, le serveur est une file d’attente à guichet unique : un client lent bloque tous les autres. Avec fork, chaque conversation vit dans son propre processus et l’accueil reste libre — c’est exactement le principe d’échelle des serveurs réels, découvert ici avec un seul appel système." }
];